173	bool Halfedge_Mesh::Vertex::on_boundary() const {
174		bool bound = false;
175		HalfedgeCRef h = halfedge;
176		do {
177			bound = bound || h->face->boundary;
178			h = h->twin->next;
179		} while (!bound && h != halfedge);
180		return bound;
