227	float Halfedge_Mesh::Vertex::angle_defect() const {
228		float defect = 2.0f * PI_F;
229	
230		auto h = halfedge;
231		do {
232			 auto e0 = (h->twin->vertex->position - position);
233			 auto e1 = (h->twin->next->twin->vertex->position - position);
234			 defect -= std::acos(dot(e0.unit(), e1.unit()));
235			 h = h->twin->next;
236		} while (h != halfedge);
237	
238		return defect;
239	}
