912	Halfedge_Mesh Halfedge_Mesh::from_indexed_mesh(Indexed_Mesh const &indexed_mesh) {
913	
914		//extract vertex positions and face indices from indexed_mesh:
915		std::vector< Vec3 > indexed_vertices;
916		indexed_vertices.reserve(indexed_mesh.vertices().size());
917		for (auto const &v : indexed_mesh.vertices()) {
918			indexed_vertices.emplace_back(v.pos);
919		}
920	
921		std::vector< std::vector< Index > > indexed_faces;
922		assert(indexed_mesh.indices().size() % 3 == 0);
923		indexed_faces.reserve(indexed_mesh.indices().size() / 3);
924		for (uint32_t i = 0; i < indexed_mesh.indices().size(); i += 3) {
925			indexed_faces.emplace_back(indexed_mesh.indices().begin() + i, indexed_mesh.indices().begin() + i + 3);
926		}
927	
928		//build halfedge mesh with the extracted vertex/face data:
929		Halfedge_Mesh mesh = Halfedge_Mesh::from_indexed_faces(indexed_vertices, indexed_faces);
930	
931		//now copy corner data:
932		auto indexed_vertex = indexed_mesh.vertices().begin();
933		for (auto vertex = mesh.vertices.begin(); vertex != mesh.vertices.end(); ++vertex) {
